// banner-loader.js: prepend a comment to every matched module
module.exports = function bannerLoader(source) {
  const { text } = this.getOptions();
  return `/* ${text} */\n${source}`;
};

// build-info-plugin.js: emit build-info.json with the asset list
const { Compilation, sources } = require("webpack");
class BuildInfoPlugin {
  apply(compiler) {
    compiler.hooks.thisCompilation.tap("BuildInfoPlugin", (compilation) => {
      compilation.hooks.processAssets.tap(
        { name: "BuildInfoPlugin", stage: Compilation.PROCESS_ASSETS_STAGE_SUMMARIZE },
        (assets) => {
          const info = { builtAt: new Date().toISOString(), files: Object.keys(assets) };
          compilation.emitAsset("build-info.json", new sources.RawSource(JSON.stringify(info)));
        },
      );
    });
  }
}
module.exports = BuildInfoPlugin;
